window.ZA_CATALOG = {"generated": "2026-10-07T19:46:04", "videos": [{"id": "h3", "title": "MiniMax H3で動画を作るのだ！", "kicker": "ずんだもん解説", "fullTitle": "【ずんだもん解説】MiniMax H3で動画を作るのだ！", "display": [[{"t": "MiniMax H3", "accent": true}], [{"t": "で動画を作るのだ！", "accent": false}]], "badge": "ずんだもん解説", "lede": "文章・画像・音声から「声つき動画」を作る最新AI", "series": "ずんだもんのAIツール解説", "duration": 280.89, "date": "2026-10-07T13:54:51", "video": {"src": "https://github.com/dikmri/zunda-archive/releases/download/videos/h3.mp4?v=4a3f25b1a114b6e0bf", "width": 1920, "height": 1080, "fps": 30, "size": 77853275, "hls": "data/h3/video.m3u8?v=4a3f25b1a114b6e0bf"}, "poster": "data/h3/poster.jpg?v=4a3f25b1a114b6e0bf", "preview": "data/h3/preview.mp4?v=4a3f25b1a114b6e0bf", "sprite": {"interval": 2, "count": 141, "cols": 10, "rows": 15, "w": 160, "h": 90, "src": "data/h3/sprite.jpg?v=4a3f25b1a114b6e0bf"}, "toc": [{"kind": "opening", "num": null, "title": "オープニング", "start": 0.3, "end": 22.26, "scene": 0, "chapter": null, "thumb": "data/h3/thumbs/00.jpg?v=4a3f25b1a114b6e0bf"}, {"kind": "chapter", "num": "その1", "title": "MiniMax H3ってなに？", "start": 22.26, "end": 26.26, "scene": 1, "chapter": 1, "thumb": "data/h3/thumbs/01.jpg?v=4a3f25b1a114b6e0bf"}, {"kind": "scene", "num": null, "title": "MiniMax H3ってなに？", "start": 26.26, "end": 63.71, "scene": 2, "chapter": 1, "thumb": "data/h3/thumbs/02.jpg?v=4a3f25b1a114b6e0bf"}, {"kind": "scene", "num": null, "title": "H3のスペック", "start": 63.71, "end": 96.5, "scene": 3, "chapter": 1, "thumb": "data/h3/thumbs/03.jpg?v=4a3f25b1a114b6e0bf"}, {"kind": "chapter", "num": "その2", "title": "3つの作り方", "start": 96.5, "end": 100.81, "scene": 4, "chapter": 4, "thumb": "data/h3/thumbs/04.jpg?v=4a3f25b1a114b6e0bf"}, {"kind": "scene", "num": null, "title": "H3の3つの作り方", "start": 100.81, "end": 141.45, "scene": 5, "chapter": 4, "thumb": "data/h3/thumbs/05.jpg?v=4a3f25b1a114b6e0bf"}, {"kind": "chapter", "num": "その3", "title": "プロンプトのコツ", "start": 141.45, "end": 145.43, "scene": 6, "chapter": 6, "thumb": "data/h3/thumbs/06.jpg?v=4a3f25b1a114b6e0bf"}, {"kind": "scene", "num": null, "title": "プロンプトは3つに分けて書く", "start": 145.43, "end": 174.18, "scene": 7, "chapter": 6, "thumb": "data/h3/thumbs/07.jpg?v=4a3f25b1a114b6e0bf"}, {"kind": "scene", "num": null, "title": "例：ずんだ餅を食べるショート動画", "start": 174.18, "end": 204.62, "scene": 8, "chapter": 6, "thumb": "data/h3/thumbs/08.jpg?v=4a3f25b1a114b6e0bf"}, {"kind": "chapter", "num": "その4", "title": "使い方と料金", "start": 204.62, "end": 208.3, "scene": 9, "chapter": 9, "thumb": "data/h3/thumbs/09.jpg?v=4a3f25b1a114b6e0bf"}, {"kind": "scene", "num": null, "title": "どこで使える？いくらかかる？", "start": 208.3, "end": 247.09, "scene": 10, "chapter": 9, "thumb": "data/h3/thumbs/10.jpg?v=4a3f25b1a114b6e0bf"}, {"kind": "scene", "num": null, "title": "まとめ", "start": 247.09, "end": 270.85, "scene": 11, "chapter": 9, "thumb": "data/h3/thumbs/11.jpg?v=4a3f25b1a114b6e0bf"}, {"kind": "ending", "num": null, "title": "エンディング", "start": 270.85, "end": 278.39, "scene": 12, "chapter": 9, "thumb": "data/h3/thumbs/12.jpg?v=4a3f25b1a114b6e0bf"}], "lines": [{"who": "zundamon", "text": "ずんだもんなのだ！今日は話題の動画生成AIを紹介するのだ！", "start": 0.8, "end": 5.24, "scene": 0, "rich": "ずんだもんなのだ！今日は話題の**動画生成AI**を紹介するのだ！"}, {"who": "metan", "text": "四国めたんよ。MiniMaxの新しいモデル、MiniMax H3のことね。", "start": 5.49, "end": 10.72, "scene": 0, "rich": "四国めたんよ。MiniMaxの新しいモデル、**MiniMax H3**のことね。"}, {"who": "zundamon", "text": "そうなのだ！文章を書くだけで、声や効果音まで入った動画ができるらしいのだ！", "start": 10.97, "end": 16.36, "scene": 0}, {"who": "metan", "text": "今回は、H3で何ができて、どう使えばいいのかを順番に見ていきましょう。", "start": 16.61, "end": 21.56, "scene": 0}, {"who": "zundamon", "text": "まずは、H3の正体からなのだ！", "start": 22.76, "end": 25.56, "scene": 1}, {"who": "metan", "text": "H3は、中国のAI企業MiniMaxが作った動画生成モデルよ。", "start": 26.76, "end": 31.45, "scene": 2}, {"who": "metan", "text": "発表されたのは、2026年7月31日ね。", "start": 31.7, "end": 35.5, "scene": 2}, {"who": "zundamon", "text": "MiniMaxって、どこかで聞いたことがあるのだ。", "start": 35.75, "end": 38.75, "scene": 2}, {"who": "metan", "text": "動画AIの「Hailuo」シリーズで知られている会社ね。", "start": 39.0, "end": 42.57, "scene": 2}, {"who": "zundamon", "text": "なるほどなのだ。それで、H3は何がすごいのだ？", "start": 42.82, "end": 46.74, "scene": 2}, {"who": "metan", "text": "一番の特徴は、オムニモーダルであること。", "start": 46.99, "end": 49.7, "scene": 2, "rich": "一番の特徴は、**オムニモーダル**であること。"}, {"who": "metan", "text": "文章・画像・動画・音声を、ひとつのモデルでまとめて理解できるの。", "start": 49.95, "end": 54.79, "scene": 2}, {"who": "zundamon", "text": "全部まとめて読み込めるのだ！？", "start": 55.04, "end": 57.08, "scene": 2}, {"who": "metan", "text": "そう。だから「この写真の人物が、この声で話す動画」みたいな注文ができるのよ。", "start": 57.33, "end": 63.01, "scene": 2}, {"who": "metan", "text": "次はスペックを見てみましょう。", "start": 64.21, "end": 65.83, "scene": 3}, {"who": "metan", "text": "解像度は最大2K。", "start": 66.08, "end": 67.73, "scene": 3, "rich": "解像度は最大**2K**。"}, {"who": "metan", "text": "1回の生成で作れる長さは、最大15秒よ。", "start": 67.98, "end": 71.42, "scene": 3, "rich": "1回の生成で作れる長さは、最大**15秒**よ。"}, {"who": "zundamon", "text": "ショート動画なら、これだけで1本できちゃうのだ！", "start": 71.67, "end": 74.65, "scene": 3}, {"who": "metan", "text": "そして注目なのが音。映像と一緒に、ステレオの音声も同時に作られるの。", "start": 74.9, "end": 80.0, "scene": 3, "rich": "そして注目なのが音。映像と一緒に、**ステレオの音声**も同時に作られるの。"}, {"who": "zundamon", "text": "えっ、セリフも効果音も、あとから付けなくていいのだ？", "start": 80.25, "end": 84.33, "scene": 3}, {"who": "metan", "text": "ええ。セリフ、効果音、環境音までまとめて出てくるわ。", "start": 84.58, "end": 88.97, "scene": 3}, {"who": "metan", "text": "プロンプトも、APIなら最大7000文字まで書けるわ。", "start": 89.22, "end": 92.81, "scene": 3}, {"who": "metan", "text": "細かい演出まで、しっかり指示できるわね。", "start": 93.06, "end": 95.8, "scene": 3}, {"who": "zundamon", "text": "H3では、どうやって動画を作るのだ？", "start": 97.0, "end": 100.11, "scene": 4}, {"who": "metan", "text": "大きく分けて、3つの作り方があるわ。", "start": 101.31, "end": 103.85, "scene": 5}, {"who": "metan", "text": "1つ目は、文章だけで作る方法。映像も音も、ゼロから組み立ててくれるの。", "start": 104.1, "end": 109.39, "scene": 5}, {"who": "metan", "text": "2つ目は、画像から作る方法。最初のコマや最後のコマを、画像で指定できるわ。", "start": 109.64, "end": 115.13, "scene": 5}, {"who": "zundamon", "text": "最初と最後を決めたら、その間をつないでくれるのだ？", "start": 115.38, "end": 118.98, "scene": 5}, {"who": "metan", "text": "その通り。登場人物の見た目をそろえたいときにも便利ね。", "start": 119.23, "end": 122.89, "scene": 5}, {"who": "metan", "text": "3つ目は参照生成。お手本になる素材を渡して作る方法よ。", "start": 123.14, "end": 127.4, "scene": 5}, {"who": "metan", "text": "画像は9枚まで、動画と音声はそれぞれ3本まで渡せるの。", "start": 127.65, "end": 131.64, "scene": 5}, {"who": "zundamon", "text": "ボクの写真とボクの声を渡せば、ボクが主役の動画も作れちゃうのだ！", "start": 131.89, "end": 136.51, "scene": 5}, {"who": "metan", "text": "ふふ、まさにそういう使い方ができるのが、H3の強みね。", "start": 136.76, "end": 140.75, "scene": 5}, {"who": "zundamon", "text": "でも、プロンプトってどう書けばいいのだ？", "start": 141.95, "end": 144.73, "scene": 6}, {"who": "metan", "text": "H3向けには、内容を3つの項目に分けて書くと伝わりやすいわ。", "start": 145.93, "end": 150.31, "scene": 7}, {"who": "metan", "text": "1つ目は、映像とセリフの流れ。ショットごとに、時間の順番で書いていくの。", "start": 150.56, "end": 155.72, "scene": 7}, {"who": "metan", "text": "2つ目は環境音。足音や雨の音など、その場で鳴っている音ね。", "start": 155.97, "end": 160.43, "scene": 7}, {"who": "metan", "text": "3つ目がBGM。登場人物には聞こえない、視聴者向けの音楽よ。", "start": 160.68, "end": 165.5, "scene": 7}, {"who": "zundamon", "text": "音を種類ごとに分けて書くのがポイントなのだ。", "start": 165.75, "end": 168.54, "scene": 7}, {"who": "metan", "text": "カメラワークは、動きの種類と大きさ、速さの3つをセットで書くといいわ。", "start": 168.79, "end": 173.48, "scene": 7}, {"who": "zundamon", "text": "じゃあ、ボクがずんだ餅を食べる動画を考えてみるのだ！", "start": 174.68, "end": 178.55, "scene": 8}, {"who": "metan", "text": "いいわね。まずは、映像とセリフを時間の順番に書くわ。", "start": 178.8, "end": 182.66, "scene": 8}, {"who": "metan", "text": "セリフは話す人に番号をつけて、言葉そのものはタグの中に入れるの。", "start": 182.91, "end": 187.11, "scene": 8}, {"who": "zundamon", "text": "日本語のセリフも、そのまま書けばいいのだ？", "start": 187.36, "end": 190.39, "scene": 8}, {"who": "metan", "text": "ええ。言語を指定すれば、日本語のまま書いて大丈夫よ。", "start": 190.64, "end": 194.72, "scene": 8}, {"who": "metan", "text": "続けて、環境音。", "start": 194.97, "end": 196.51, "scene": 8}, {"who": "metan", "text": "最後に、BGMを書けば完成よ。", "start": 196.76, "end": 199.38, "scene": 8}, {"who": "zundamon", "text": "お祭りの音もBGMも付いた動画になるのだ！楽しみなのだ！", "start": 199.63, "end": 203.92, "scene": 8}, {"who": "zundamon", "text": "H3は、どこで使えるのだ？", "start": 205.12, "end": 207.6, "scene": 9}, {"who": "metan", "text": "手軽に試すなら、HailuoのアプリやWebサイトね。", "start": 208.8, "end": 211.76, "scene": 10}, {"who": "metan", "text": "プログラムから使うなら、APIね。", "start": 212.01, "end": 214.47, "scene": 10}, {"who": "metan", "text": "タスクを作って、完成を待ってから動画をダウンロードする流れよ。", "start": 214.72, "end": 218.6, "scene": 10}, {"who": "zundamon", "text": "注文して、できあがるのを待つ感じなのだ。", "start": 218.85, "end": 221.77, "scene": 10}, {"who": "metan", "text": "気になる料金は、公式発表によると……", "start": 222.02, "end": 224.68, "scene": 10}, {"who": "metan", "text": "2Kでも1秒あたりの価格が、主流モデルの3分の1未満だそうよ。", "start": 224.93, "end": 229.43, "scene": 10}, {"who": "zundamon", "text": "安いのは助かるのだ！ボクのお小遣いでも作れるかもしれないのだ。", "start": 229.68, "end": 233.94, "scene": 10}, {"who": "metan", "text": "さらに8月3日には、モデルのウェイトもHugging Faceで公開されたわ。", "start": 234.19, "end": 238.48, "scene": 10}, {"who": "metan", "text": "ただし、ライセンスには地域などの条件があるから、使う前に必ず確認してね。", "start": 238.73, "end": 243.95, "scene": 10}, {"who": "zundamon", "text": "ちゃんと規約を読むのが大事なのだ。", "start": 244.2, "end": 246.39, "scene": 10}, {"who": "metan", "text": "最後に、まとめるわね。", "start": 247.59, "end": 249.25, "scene": 11}, {"who": "zundamon", "text": "H3は、文章・画像・動画・音声をまとめて扱える動画生成AIなのだ。", "start": 249.5, "end": 256.1, "scene": 11}, {"who": "metan", "text": "最大2Kで15秒、声や効果音まで一度に作れるわ。", "start": 256.35, "end": 260.23, "scene": 11}, {"who": "zundamon", "text": "作り方は、テキスト、画像、参照の3通りなのだ。", "start": 260.48, "end": 264.72, "scene": 11}, {"who": "metan", "text": "プロンプトは、映像とセリフ、環境音、BGMに分けて書くのがコツよ。", "start": 264.97, "end": 270.15, "scene": 11}, {"who": "zundamon", "text": "今日はここまでなのだ！ご視聴ありがとうなのだ！", "start": 271.35, "end": 274.38, "scene": 12}, {"who": "metan", "text": "気に入ったら、高評価とチャンネル登録もよろしくね。", "start": 274.63, "end": 277.69, "scene": 12}], "cast": {"metan": {"name": "四国めたん", "color": "#d43a86", "position": "left", "voice": "VOICEVOX:四国めたん", "stats": {"lines": 43, "seconds": 166.78, "chars": 1147, "ending": ["るの", 5]}, "portrait": {"idle": "data/cast/metan/idle.webp?v=3-1a114ac0292", "blink": "data/cast/metan/blink.webp?v=3-1a114ac0292", "talk": "data/cast/metan/talk.webp?v=3-1a114ac0292", "joy": "data/cast/metan/joy.webp?v=3-1a114ac0292"}}, "zundamon": {"name": "ずんだもん", "color": "#2f9a3a", "position": "right", "voice": "VOICEVOX:ずんだもん", "stats": {"lines": 23, "seconds": 82.46, "chars": 546, "ending": ["のだ", 29]}, "portrait": {"idle": "data/cast/zundamon/idle.webp?v=3-1a114abfbbf", "blink": "data/cast/zundamon/blink.webp?v=3-1a114abfbbf", "talk": "data/cast/zundamon/talk.webp?v=3-1a114abfbbf", "joy": "data/cast/zundamon/joy.webp?v=3-1a114abfbbf"}}}, "summary": [{"text": "文章・画像・動画・音声をまとめて扱う動画AI", "sub": ""}, {"text": "最大2K・15秒。声や効果音も**同時に生成**", "sub": ""}, {"text": "作り方は「テキスト」「画像」「参照」の3通り", "sub": ""}, {"text": "プロンプトは「映像とセリフ」「環境音」「BGM」に分ける", "sub": ""}], "sources": [], "credits": [["音声", "VOICEVOX:ずんだもん / VOICEVOX:四国めたん"], ["立ち絵", "坂本アヒル"], ["音楽", "音楽：魔王魂"], ["効果音", "効果音ラボ"], ["フォント", "M PLUS Rounded 1c / Dela Gothic One"], ["出典", "MiniMax公式ブログ・APIドキュメントほか（2026年10月時点）"]], "no": 1}, {"id": "kiritan", "title": "WAI-AnimaとMiniMax H3で、きりたんのアニメPVを作るのだ！", "kicker": "ずんだもん解説", "fullTitle": "【ずんだもん解説】WAI-AnimaとMiniMax H3で、きりたんのアニメPVを作るのだ！", "display": [[{"t": "WAI-Anima×H3", "accent": true}], [{"t": "でアニメPVを作るのだ！", "accent": false}]], "badge": "ずんだもん解説", "lede": "環境構築から動画まで、ぜんぶ自分のPCで", "series": "ずんだもんのAIツール解説", "duration": 306.53, "date": "2026-10-07T15:25:06", "video": {"src": "https://github.com/dikmri/zunda-archive/releases/download/videos/kiritan.mp4?v=554623a1a115097e4d", "width": 1920, "height": 1080, "fps": 30, "size": 89416250, "hls": "data/kiritan/video.m3u8?v=554623a1a115097e4d"}, "poster": "data/kiritan/poster.jpg?v=554623a1a115097e4d", "preview": "data/kiritan/preview.mp4?v=554623a1a115097e4d", "sprite": {"interval": 2, "count": 154, "cols": 10, "rows": 16, "w": 160, "h": 90, "src": "data/kiritan/sprite.jpg?v=554623a1a115097e4d"}, "toc": [{"kind": "opening", "num": null, "title": "オープニング", "start": 0.3, "end": 20.71, "scene": 0, "chapter": null, "thumb": "data/kiritan/thumbs/00.jpg?v=554623a1a115097e4d"}, {"kind": "scene", "num": null, "title": "作業は3ステップ", "start": 20.71, "end": 41.92, "scene": 1, "chapter": null, "thumb": "data/kiritan/thumbs/01.jpg?v=554623a1a115097e4d"}, {"kind": "chapter", "num": "その1", "title": "準備と環境構築", "start": 41.92, "end": 45.65, "scene": 2, "chapter": 2, "thumb": "data/kiritan/thumbs/02.jpg?v=554623a1a115097e4d"}, {"kind": "scene", "num": null, "title": "必要なもの", "start": 45.65, "end": 75.17, "scene": 3, "chapter": 2, "thumb": "data/kiritan/thumbs/03.jpg?v=554623a1a115097e4d"}, {"kind": "scene", "num": null, "title": "ComfyUI の入れ方", "start": 75.17, "end": 99.87, "scene": 4, "chapter": 2, "thumb": "data/kiritan/thumbs/04.jpg?v=554623a1a115097e4d"}, {"kind": "chapter", "num": "その2", "title": "WAI-Animaで絵を描く", "start": 99.87, "end": 103.21, "scene": 5, "chapter": 5, "thumb": "data/kiritan/thumbs/05.jpg?v=554623a1a115097e4d"}, {"kind": "scene", "num": null, "title": "WAI-Anima を入れる", "start": 103.21, "end": 124.0, "scene": 6, "chapter": 5, "thumb": "data/kiritan/thumbs/06.jpg?v=554623a1a115097e4d"}, {"kind": "scene", "num": null, "title": "プロンプトはタグを順番に並べる", "start": 124.0, "end": 151.68, "scene": 7, "chapter": 5, "thumb": "data/kiritan/thumbs/07.jpg?v=554623a1a115097e4d"}, {"kind": "scene", "num": null, "title": "生成した絵", "start": 151.68, "end": 171.59, "scene": 8, "chapter": 5, "thumb": "data/kiritan/thumbs/08.jpg?v=554623a1a115097e4d"}, {"kind": "chapter", "num": "その3", "title": "MiniMax H3で動かす", "start": 171.59, "end": 174.88, "scene": 9, "chapter": 9, "thumb": "data/kiritan/thumbs/09.jpg?v=554623a1a115097e4d"}, {"kind": "scene", "num": null, "title": "MiniMax H3 を入れる", "start": 174.88, "end": 203.49, "scene": 10, "chapter": 9, "thumb": "data/kiritan/thumbs/10.jpg?v=554623a1a115097e4d"}, {"kind": "scene", "num": null, "title": "今回の設定", "start": 203.49, "end": 219.6, "scene": 11, "chapter": 9, "thumb": "data/kiritan/thumbs/11.jpg?v=554623a1a115097e4d"}, {"kind": "scene", "num": null, "title": "H3 のプロンプト", "start": 219.6, "end": 254.02, "scene": 12, "chapter": 9, "thumb": "data/kiritan/thumbs/12.jpg?v=554623a1a115097e4d"}, {"kind": "scene", "num": null, "title": "守ること・コツ", "start": 254.02, "end": 278.88, "scene": 14, "chapter": 9, "thumb": "data/kiritan/thumbs/13.jpg?v=554623a1a115097e4d"}, {"kind": "scene", "num": null, "title": "まとめ", "start": 278.88, "end": 296.06, "scene": 15, "chapter": 9, "thumb": "data/kiritan/thumbs/14.jpg?v=554623a1a115097e4d"}, {"kind": "ending", "num": null, "title": "エンディング", "start": 296.06, "end": 304.04, "scene": 16, "chapter": 9, "thumb": "data/kiritan/thumbs/15.jpg?v=554623a1a115097e4d"}], "lines": [{"who": "zundamon", "text": "ずんだもんなのだ！今日は、自分のパソコンでアニメ作りに挑戦するのだ！", "start": 0.8, "end": 5.63, "scene": 0}, {"who": "metan", "text": "四国めたんよ。絵はWAI-Anima、動画はMiniMax H3で作るのね。", "start": 5.88, "end": 11.18, "scene": 0}, {"who": "zundamon", "text": "きりたんに「わたしのPVを作ってください」って頼まれたのだ！", "start": 11.43, "end": 16.06, "scene": 0}, {"who": "metan", "text": "いいわね。環境構築から、順番にやっていきましょう。", "start": 16.31, "end": 20.01, "scene": 0}, {"who": "metan", "text": "まずは、AIを動かすアプリのComfyUIを入れるわ。", "start": 21.21, "end": 24.76, "scene": 1}, {"who": "metan", "text": "次に、WAI-Animaで、きりたんの絵を描く。", "start": 25.01, "end": 28.54, "scene": 1}, {"who": "metan", "text": "最後に、MiniMax H3で、その絵を動かすの。", "start": 28.79, "end": 32.7, "scene": 1}, {"who": "zundamon", "text": "しかも全部、自分のパソコンの中でできるのだ？", "start": 32.95, "end": 36.39, "scene": 1}, {"who": "metan", "text": "そう。ネットに画像を送らずに作れるのが、ローカル生成のいいところね。", "start": 36.64, "end": 41.22, "scene": 1}, {"who": "zundamon", "text": "まずは、何を用意すればいいのだ？", "start": 42.42, "end": 44.95, "scene": 2}, {"who": "metan", "text": "動画まで作るなら、VRAM16GBのNVIDIA製GPUが目安よ。", "start": 46.15, "end": 50.76, "scene": 3}, {"who": "zundamon", "text": "ボクのパソコンは、RTX 5060 Tiの16GBなのだ！", "start": 51.01, "end": 56.74, "scene": 3}, {"who": "metan", "text": "ちょうどいいわね。ストレージは、モデルだけで約50GB使うわ。", "start": 56.99, "end": 60.98, "scene": 3}, {"who": "metan", "text": "アプリはComfyUI。AIの部品を、線でつないで動かす道具よ。", "start": 61.23, "end": 66.03, "scene": 3}, {"who": "metan", "text": "メインメモリも多いほど安心ね。このパソコンは64GBよ。", "start": 66.28, "end": 70.28, "scene": 3}, {"who": "zundamon", "text": "GPUに入りきらない分は、メモリに逃がしてくれるのだ。", "start": 70.53, "end": 74.47, "scene": 3}, {"who": "metan", "text": "ComfyUIの入れ方は、とても簡単よ。", "start": 75.67, "end": 78.33, "scene": 4}, {"who": "metan", "text": "GitHubから、Windows用のポータブル版をダウンロードして……", "start": 78.58, "end": 82.12, "scene": 4}, {"who": "metan", "text": "7-Zipで展開したら……", "start": 82.37, "end": 83.89, "scene": 4}, {"who": "metan", "text": "run_nvidia_gpu.batをダブルクリック。ブラウザに画面が開くわ。", "start": 84.14, "end": 89.64, "scene": 4}, {"who": "zundamon", "text": "インストール作業が、ほとんどないのだ！", "start": 89.89, "end": 92.43, "scene": 4}, {"who": "metan", "text": "モデルは、modelsフォルダの中の決まった場所に置くの。", "start": 92.68, "end": 95.74, "scene": 4}, {"who": "metan", "text": "置き場所を間違えると読み込めないから、注意してね。", "start": 95.99, "end": 99.17, "scene": 4}, {"who": "zundamon", "text": "いよいよ、きりたんを描くのだ！", "start": 100.37, "end": 102.51, "scene": 5}, {"who": "metan", "text": "WAI-Animaは、アニメ絵が得意なAnimaを、さらに鍛えたモデルよ。", "start": 103.71, "end": 108.13, "scene": 6}, {"who": "metan", "text": "配布元のCivitaiは、ダウンロードにログインが必要ね。", "start": 108.38, "end": 111.69, "scene": 6}, {"who": "metan", "text": "本体、文章を読む部品、VAEの3つを、それぞれのフォルダに置くわ。", "start": 111.94, "end": 117.16, "scene": 6}, {"who": "zundamon", "text": "3つそろわないと、動かないのだ？", "start": 117.41, "end": 119.94, "scene": 6}, {"who": "metan", "text": "そう。どれか1つでも欠けると、エラーになるわ。", "start": 120.19, "end": 123.3, "scene": 6}, {"who": "metan", "text": "指示は、タグを並べて書くの。順番が大事よ。", "start": 124.5, "end": 127.69, "scene": 7}, {"who": "metan", "text": "品質、年齢区分、キャラ名、作品名、そのあとに内容ね。", "start": 127.94, "end": 132.83, "scene": 7}, {"who": "metan", "text": "年齢区分はsafe。全年齢向けの絵にするための指定よ。", "start": 133.08, "end": 136.93, "scene": 7}, {"who": "zundamon", "text": "キャラ名は「tohoku kiritan」で通じるのだ？", "start": 137.18, "end": 140.9, "scene": 7}, {"who": "metan", "text": "ええ。有名なキャラなら、名前だけでもかなり再現できるわ。", "start": 141.15, "end": 145.39, "scene": 7}, {"who": "metan", "text": "設定は28ステップ、CFG4.5。サイズは動画に合わせて横長よ。", "start": 145.64, "end": 150.98, "scene": 7}, {"who": "metan", "text": "実際に生成した結果が、こちらよ。", "start": 152.18, "end": 154.59, "scene": 8}, {"who": "zundamon", "text": "きりたんぽを持ったきりたんなのだ！かわいいのだ！", "start": 154.84, "end": 157.88, "scene": 8}, {"who": "metan", "text": "ゲームに集中する場面と、勝って喜ぶ場面も作ってみたわ。", "start": 158.13, "end": 162.1, "scene": 8}, {"who": "zundamon", "text": "1枚あたり、どのくらいかかったのだ？", "start": 162.35, "end": 165.03, "scene": 8}, {"who": "metan", "text": "このパソコンだと、1枚およそ20秒ね。", "start": 165.28, "end": 168.09, "scene": 8}, {"who": "zundamon", "text": "はやいのだ！何枚でも試せちゃうのだ。", "start": 168.34, "end": 170.89, "scene": 8}, {"who": "zundamon", "text": "次は、この絵を動かすのだ！", "start": 172.09, "end": 174.18, "scene": 9}, {"who": "metan", "text": "H3は、ComfyUI用にまとめられたファイルを使うと楽よ。", "start": 175.38, "end": 179.37, "scene": 10}, {"who": "metan", "text": "本体は約21GB。画像と文章から動画を作る版を選ぶわ。", "start": 179.62, "end": 183.97, "scene": 10}, {"who": "metan", "text": "文章を理解する部品は、RTX 50シリーズ向けの軽い版ね。", "start": 184.22, "end": 189.02, "scene": 10}, {"who": "metan", "text": "VAEは映像用と音声用の2つ。H3は、音も一緒に作るからね。", "start": 189.27, "end": 194.49, "scene": 10}, {"who": "metan", "text": "それと、少ないステップで仕上げる高速化LoRAも入れておくわ。", "start": 194.74, "end": 198.46, "scene": 10}, {"who": "zundamon", "text": "全部で45GBくらいあるのだ……ダウンロードが大変なのだ。", "start": 198.71, "end": 202.79, "scene": 10}, {"who": "metan", "text": "今回は、さっきの絵を最初のコマにして動かすわ。", "start": 203.99, "end": 207.1, "scene": 11}, {"who": "metan", "text": "解像度は480p、長さは約5秒、10ステップで生成したの。", "start": 207.35, "end": 212.48, "scene": 11}, {"who": "zundamon", "text": "時間は、どのくらいかかったのだ？", "start": 212.73, "end": 215.1, "scene": 11}, {"who": "metan", "text": "1本およそ4分。モデルの読み込みも含めた時間よ。", "start": 215.35, "end": 218.9, "scene": 11}, {"who": "metan", "text": "プロンプトは英語で、時間の流れに沿って書くの。", "start": 220.1, "end": 223.07, "scene": 12}, {"who": "metan", "text": "最初の行で「1枚目の画像から始める」と指定するのがポイントよ。", "start": 223.32, "end": 228.02, "scene": 12}, {"who": "metan", "text": "セリフは、日本語のまま書けば声になるわ。", "start": 228.27, "end": 230.89, "scene": 12}, {"who": "metan", "text": "あとは、環境音とBGMを分けて書けば完成ね。", "start": 231.14, "end": 234.5, "scene": 12}, {"who": "zundamon", "text": "きりたんがしゃべるのだ！？楽しみなのだ！", "start": 234.75, "end": 237.41, "scene": 12}, {"who": "metan", "text": "それじゃあ、完成した動画を見てみましょう。", "start": 238.61, "end": 241.2, "scene": 13}, {"who": "zundamon", "text": "動いたのだ！声も音楽も、ちゃんと入ってるのだ！", "start": 247.3, "end": 250.8, "scene": 13}, {"who": "metan", "text": "1枚の絵から、ここまで作れるのよ。", "start": 251.05, "end": 253.32, "scene": 13}, {"who": "metan", "text": "最後に、注意点を3つ。", "start": 254.52, "end": 256.48, "scene": 14}, {"who": "metan", "text": "WAI-Animaは、モデル自体は非商用。生成した画像は使えるわ。", "start": 256.73, "end": 261.61, "scene": 14}, {"who": "metan", "text": "H3の動画を公開するときは、AI生成だと分かるようにしてね。", "start": 261.86, "end": 266.38, "scene": 14}, {"who": "metan", "text": "きりたんのガイドラインも守って、イメージを損なう使い方はしないこと。", "start": 266.63, "end": 270.84, "scene": 14}, {"who": "metan", "text": "そしてVRAMのコツ。重いアプリを閉じて、短い尺から試すこと。", "start": 271.09, "end": 275.27, "scene": 14}, {"who": "zundamon", "text": "約束を守って、楽しく作るのだ！", "start": 275.52, "end": 278.18, "scene": 14}, {"who": "metan", "text": "まとめるわね。", "start": 279.38, "end": 280.25, "scene": 15}, {"who": "zundamon", "text": "ComfyUIを入れて、モデルを決まった場所に置くのだ。", "start": 280.5, "end": 284.06, "scene": 15}, {"who": "metan", "text": "WAI-Animaは、タグを順番どおりに並べて描くの。", "start": 284.31, "end": 287.78, "scene": 15}, {"who": "zundamon", "text": "H3なら、1枚の絵から声つきの動画が作れるのだ。", "start": 288.03, "end": 292.11, "scene": 15}, {"who": "metan", "text": "そして、規約とガイドラインを守って楽しみましょう。", "start": 292.36, "end": 295.36, "scene": 15}, {"who": "zundamon", "text": "今日はここまでなのだ！きりたんにも、喜んでもらえたのだ！", "start": 296.56, "end": 300.51, "scene": 16}, {"who": "metan", "text": "高評価とチャンネル登録も、よろしくね。", "start": 300.76, "end": 303.34, "scene": 16}], "cast": {"metan": {"name": "四国めたん", "color": "#d43a86", "position": "left", "voice": "VOICEVOX:四国めたん", "stats": {"lines": 51, "seconds": 190.24, "chars": 1347, "ending": ["るわ", 5]}, "portrait": {"idle": "data/cast/metan/idle.webp?v=3-1a114ac0292", "blink": "data/cast/metan/blink.webp?v=3-1a114ac0292", "talk": "data/cast/metan/talk.webp?v=3-1a114ac0292", "joy": "data/cast/metan/joy.webp?v=3-1a114ac0292"}}, "zundamon": {"name": "ずんだもん", "color": "#2f9a3a", "position": "right", "voice": "VOICEVOX:ずんだもん", "stats": {"lines": 22, "seconds": 73.25, "chars": 489, "ending": ["のだ", 28]}, "portrait": {"idle": "data/cast/zundamon/idle.webp?v=3-1a114abfbbf", "blink": "data/cast/zundamon/blink.webp?v=3-1a114abfbbf", "talk": "data/cast/zundamon/talk.webp?v=3-1a114abfbbf", "joy": "data/cast/zundamon/joy.webp?v=3-1a114abfbbf"}}}, "summary": [{"text": "ComfyUI を入れて、モデルを決まった場所に置く", "sub": ""}, {"text": "WAI-Anima はタグを順番どおりに並べて描く", "sub": ""}, {"text": "H3 なら、1枚の絵から**声つきの動画**にできる", "sub": ""}, {"text": "規約とガイドラインを守って楽しむ", "sub": ""}], "sources": [], "credits": [["音声", "VOICEVOX:ずんだもん / VOICEVOX:四国めたん"], ["立ち絵", "坂本アヒル"], ["作例のキャラ", "東北きりたん（東北ずん子・ずんだもんプロジェクト）"], ["画像生成", "WAI-ANIMA（WAI0731）/ Anima（CircleStone Labs・Comfy Org）"], ["動画生成", "MiniMax H3（MiniMax）※作例の画像と動画は AI 生成"], ["音楽 / 効果音", "音楽：魔王魂 / 効果音ラボ"], ["フォント", "M PLUS Rounded 1c / Dela Gothic One"]], "no": 2}, {"id": "promo", "title": "頼むだけで解説動画ができるスキル zundamon-video", "kicker": "ずんだもん解説", "fullTitle": "【ずんだもん解説】頼むだけで解説動画ができるスキル zundamon-video", "display": [[{"t": "zundamon-video", "accent": true}], [{"t": "頼むだけで解説動画！", "accent": false}]], "badge": "Claude Code スキル", "lede": "ずんだもん解説動画を、調査から書き出しまで", "series": "zundamon-video の紹介", "duration": 134.55, "date": "2026-10-07T16:23:17", "video": {"src": "https://github.com/dikmri/zunda-archive/releases/download/videos/promo.mp4?v=26331cb1a1153ec571", "width": 1920, "height": 1080, "fps": 30, "size": 40055243, "hls": "data/promo/video.m3u8?v=26331cb1a1153ec571"}, "poster": "data/promo/poster.jpg?v=26331cb1a1153ec571", "preview": "data/promo/preview.mp4?v=26331cb1a1153ec571", "sprite": {"interval": 2, "count": 68, "cols": 10, "rows": 7, "w": 160, "h": 90, "src": "data/promo/sprite.jpg?v=26331cb1a1153ec571"}, "toc": [{"kind": "opening", "num": null, "title": "オープニング", "start": 0.3, "end": 10.14, "scene": 0, "chapter": null, "thumb": "data/promo/thumbs/00.jpg?v=26331cb1a1153ec571"}, {"kind": "scene", "num": null, "title": "Claude Code に一言たのむだけ", "start": 10.14, "end": 29.37, "scene": 1, "chapter": null, "thumb": "data/promo/thumbs/01.jpg?v=26331cb1a1153ec571"}, {"kind": "scene", "num": null, "title": "こんなことが自動でできる", "start": 29.37, "end": 53.02, "scene": 2, "chapter": null, "thumb": "data/promo/thumbs/02.jpg?v=26331cb1a1153ec571"}, {"kind": "scene", "num": null, "title": "実際に作った動画", "start": 53.02, "end": 70.71, "scene": 3, "chapter": null, "thumb": "data/promo/thumbs/03.jpg?v=26331cb1a1153ec571"}, {"kind": "scene", "num": null, "title": "AI の作例も入れられる", "start": 70.71, "end": 81.89, "scene": 4, "chapter": null, "thumb": "data/promo/thumbs/04.jpg?v=26331cb1a1153ec571"}, {"kind": "scene", "num": null, "title": "動画ができるまで", "start": 81.89, "end": 102.76, "scene": 5, "chapter": null, "thumb": "data/promo/thumbs/05.jpg?v=26331cb1a1153ec571"}, {"kind": "scene", "num": null, "title": "はじめ方は5ステップ", "start": 102.76, "end": 123.44, "scene": 6, "chapter": null, "thumb": "data/promo/thumbs/06.jpg?v=26331cb1a1153ec571"}, {"kind": "ending", "num": null, "title": "エンディング", "start": 123.44, "end": 132.05, "scene": 7, "chapter": null, "thumb": "data/promo/thumbs/07.jpg?v=26331cb1a1153ec571"}], "lines": [{"who": "zundamon", "text": "ずんだもんなのだ！実はこの動画、AIが全部作ったのだ！", "start": 0.8, "end": 5.17, "scene": 0}, {"who": "metan", "text": "四国めたんよ。今日は、この動画を作ったスキルを紹介するわ。", "start": 5.42, "end": 9.44, "scene": 0}, {"who": "metan", "text": "使い方は簡単。Claude Codeに、作りたい動画を一言たのむだけよ。", "start": 10.64, "end": 15.47, "scene": 1}, {"who": "zundamon", "text": "それだけなのだ！？", "start": 15.72, "end": 16.88, "scene": 1}, {"who": "metan", "text": "調査、台本、音声、画面の確認まで、全部やってくれるの。", "start": 16.98, "end": 21.82, "scene": 1}, {"who": "metan", "text": "できあがるのは、フルHDのmp4。そのまま投稿できるわ。", "start": 22.07, "end": 26.35, "scene": 1}, {"who": "zundamon", "text": "ボクは、しゃべるだけでいいのだ！", "start": 26.6, "end": 28.67, "scene": 1}, {"who": "metan", "text": "声はVOICEVOX。ずんだもんと四国めたんの声で話すわ。", "start": 29.87, "end": 33.63, "scene": 2}, {"who": "zundamon", "text": "立ち絵は、口パクもまばたきもするのだ！", "start": 33.88, "end": 36.57, "scene": 2}, {"who": "metan", "text": "説明の図はHTMLで作るから、セリフに合わせて1つずつ出せるの。", "start": 36.82, "end": 41.44, "scene": 2}, {"who": "zundamon", "text": "字幕もBGMも効果音も、自動で入るのだ。", "start": 41.69, "end": 45.16, "scene": 2}, {"who": "metan", "text": "AIで生成した画像や動画も、そのまま埋め込めるわ。", "start": 45.41, "end": 48.86, "scene": 2}, {"who": "zundamon", "text": "5分の動画でも、書き出しは5分くらいなのだ！", "start": 49.11, "end": 52.32, "scene": 2}, {"who": "metan", "text": "実際に作った動画を見てみましょう。まずは、MiniMax H3の解説よ。", "start": 53.52, "end": 58.86, "scene": 3}, {"who": "zundamon", "text": "こっちは、きりたんのアニメPVを作る解説なのだ！", "start": 59.11, "end": 62.69, "scene": 3}, {"who": "metan", "text": "どちらも、このスキルで作った動画そのものよ。", "start": 62.94, "end": 65.63, "scene": 3}, {"who": "zundamon", "text": "数字がポンッと出たり、絵が並んだり、見ていて楽しいのだ。", "start": 65.88, "end": 70.01, "scene": 3}, {"who": "zundamon", "text": "画像生成の絵を、こんなふうに声つきの動画にもできるのだ！", "start": 71.21, "end": 75.3, "scene": 4}, {"who": "metan", "text": "ふふ、きりたんも嬉しそうね。", "start": 79.3, "end": 81.19, "scene": 4}, {"who": "metan", "text": "仕組みも見ておきましょう。台本は、JSONで書くわ。", "start": 82.39, "end": 85.73, "scene": 5}, {"who": "metan", "text": "セリフをVOICEVOXでしゃべらせて、口パクの時刻を計算するの。", "start": 85.98, "end": 89.87, "scene": 5}, {"who": "metan", "text": "画面はHTMLで作って、Playwrightで1コマずつ撮影するわ。", "start": 90.12, "end": 94.58, "scene": 5}, {"who": "metan", "text": "最後にffmpegで、音声と合わせてmp4にするの。", "start": 94.83, "end": 98.75, "scene": 5}, {"who": "zundamon", "text": "だから、何度書き出しても同じ動画になるのだ！", "start": 99.0, "end": 102.06, "scene": 5}, {"who": "metan", "text": "まずは、GitHubからリポジトリをクローンするわ。", "start": 103.26, "end": 106.13, "scene": 6}, {"who": "metan", "text": "セットアップのコマンドで、声やBGMの素材が自動でそろうの。", "start": 106.38, "end": 110.4, "scene": 6}, {"who": "metan", "text": "立ち絵だけは、配布ページの規約に同意して、自分で取ってきてね。", "start": 110.65, "end": 114.75, "scene": 6}, {"who": "metan", "text": "スキルを入れたら、あとはClaudeにたのむだけよ。", "start": 115.0, "end": 117.58, "scene": 6}, {"who": "zundamon", "text": "「〇〇を解説するずんだもん動画を作って」で、できあがりなのだ！", "start": 117.83, "end": 122.74, "scene": 6}, {"who": "zundamon", "text": "GitHubで公開中なのだ！ぜひ使ってほしいのだ！", "start": 123.94, "end": 127.49, "scene": 7}, {"who": "metan", "text": "見てくれてありがとう。あなたの動画も、楽しみにしているわ。", "start": 127.74, "end": 131.35, "scene": 7}], "cast": {"metan": {"name": "四国めたん", "color": "#d43a86", "position": "left", "voice": "VOICEVOX:四国めたん", "stats": {"lines": 19, "seconds": 72.51, "chars": 537, "ending": ["るわ", 6]}, "portrait": {"idle": "data/cast/metan/idle.webp?v=3-1a114ac0292", "blink": "data/cast/metan/blink.webp?v=3-1a114ac0292", "talk": "data/cast/metan/talk.webp?v=3-1a114ac0292", "joy": "data/cast/metan/joy.webp?v=3-1a114ac0292"}}, "zundamon": {"name": "ずんだもん", "color": "#2f9a3a", "position": "right", "voice": "VOICEVOX:ずんだもん", "stats": {"lines": 12, "seconds": 40.29, "chars": 271, "ending": ["のだ", 14]}, "portrait": {"idle": "data/cast/zundamon/idle.webp?v=3-1a114abfbbf", "blink": "data/cast/zundamon/blink.webp?v=3-1a114abfbbf", "talk": "data/cast/zundamon/talk.webp?v=3-1a114abfbbf", "joy": "data/cast/zundamon/joy.webp?v=3-1a114abfbbf"}}}, "summary": [], "sources": [], "credits": [["音声", "VOICEVOX:ずんだもん / VOICEVOX:四国めたん"], ["立ち絵", "坂本アヒル"], ["作例のキャラ", "東北きりたん（東北ずん子・ずんだもんプロジェクト）"], ["作例の生成", "WAI-ANIMA（WAI0731）/ Anima / MiniMax H3 ※作例の画像と動画は AI 生成"], ["音楽 / 効果音", "音楽：魔王魂 / 効果音ラボ"], ["フォント", "M PLUS Rounded 1c / Dela Gothic One"]], "no": 3}, {"id": "iran_war", "title": "アメリカ・イスラエル×イラン戦争 なぜ始まり、なぜ終わらないのか", "kicker": "ずんだもん解説", "fullTitle": "【ずんだもん解説】アメリカ・イスラエル×イラン戦争 なぜ始まり、なぜ終わらないのか", "display": [[{"t": "アメリカ・イスラエル", "accent": true}], [{"t": "×イラン戦争", "accent": false}]], "badge": "ずんだもんのニュース解説", "lede": "なぜ始まった？ 誰が悪い？ なぜ終わらない？\n2026年10月7日時点", "series": "ずんだもんのニュース解説（2026年10月7日時点）", "duration": 633.67, "date": "2026-10-07T17:50:08", "video": {"src": "https://github.com/dikmri/zunda-archive/releases/download/videos/iran_war.mp4?v=a6a258b1a1158e47d4", "width": 1920, "height": 1080, "fps": 30, "size": 174728587, "hls": "data/iran_war/video.m3u8?v=a6a258b1a1158e47d4"}, "poster": "data/iran_war/poster.jpg?v=a6a258b1a1158e47d4", "preview": "data/iran_war/preview.mp4?v=a6a258b1a1158e47d4", "sprite": {"interval": 4, "count": 159, "cols": 10, "rows": 16, "w": 160, "h": 90, "src": "data/iran_war/sprite.jpg?v=a6a258b1a1158e47d4"}, "toc": [{"kind": "opening", "num": null, "title": "オープニング", "start": 0.3, "end": 16.93, "scene": 0, "chapter": null, "thumb": "data/iran_war/thumbs/00.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "この動画で答える3つの疑問", "start": 16.93, "end": 37.67, "scene": 1, "chapter": null, "thumb": "data/iran_war/thumbs/01.jpg?v=a6a258b1a1158e47d4"}, {"kind": "chapter", "num": "その1", "title": "誰と誰が戦っているの？", "start": 37.67, "end": 41.96, "scene": 2, "chapter": 2, "thumb": "data/iran_war/thumbs/02.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "対立の構図", "start": 41.96, "end": 84.18, "scene": 3, "chapter": 2, "thumb": "data/iran_war/thumbs/03.jpg?v=a6a258b1a1158e47d4"}, {"kind": "chapter", "num": "その2", "title": "なぜ始まったの？", "start": 84.18, "end": 87.83, "scene": 4, "chapter": 4, "thumb": "data/iran_war/thumbs/04.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "47年続く対立", "start": 87.83, "end": 135.58, "scene": 5, "chapter": 4, "thumb": "data/iran_war/thumbs/05.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "開戦までの1年", "start": 135.58, "end": 185.56, "scene": 6, "chapter": 4, "thumb": "data/iran_war/thumbs/06.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "2026年2月28日 開戦", "start": 185.56, "end": 235.69, "scene": 7, "chapter": 4, "thumb": "data/iran_war/thumbs/07.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "中東全体に広がった戦争", "start": 235.69, "end": 282.23, "scene": 8, "chapter": 4, "thumb": "data/iran_war/thumbs/08.jpg?v=a6a258b1a1158e47d4"}, {"kind": "chapter", "num": "その3", "title": "停戦と崩壊の8か月", "start": 282.23, "end": 286.54, "scene": 9, "chapter": 9, "thumb": "data/iran_war/thumbs/09.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "4月〜6月：停戦と「二重封鎖」", "start": 286.54, "end": 337.29, "scene": 10, "chapter": 9, "thumb": "data/iran_war/thumbs/10.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "7月〜10月：崩れた約束", "start": 337.29, "end": 380.99, "scene": 11, "chapter": 9, "thumb": "data/iran_war/thumbs/11.jpg?v=a6a258b1a1158e47d4"}, {"kind": "chapter", "num": "その4", "title": "誰が悪いの？", "start": 380.99, "end": 384.62, "scene": 12, "chapter": 12, "thumb": "data/iran_war/thumbs/12.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "第三者はどう評価している？", "start": 384.62, "end": 445.5, "scene": 13, "chapter": 12, "thumb": "data/iran_war/thumbs/13.jpg?v=a6a258b1a1158e47d4"}, {"kind": "chapter", "num": "その5", "title": "なぜ終わらないの？", "start": 445.5, "end": 449.7, "scene": 14, "chapter": 14, "thumb": "data/iran_war/thumbs/14.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "理由1：先に求めるものが違う", "start": 449.7, "end": 480.11, "scene": 15, "chapter": 14, "thumb": "data/iran_war/thumbs/15.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "理由2：お互いに「封鎖」を続けている", "start": 480.11, "end": 512.55, "scene": 16, "chapter": 14, "thumb": "data/iran_war/thumbs/16.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "理由3・4：信用とまとめ役", "start": 512.55, "end": 550.53, "scene": 17, "chapter": 14, "thumb": "data/iran_war/thumbs/17.jpg?v=a6a258b1a1158e47d4"}, {"kind": "chapter", "num": "その6", "title": "日本への影響", "start": 550.53, "end": 555.01, "scene": 18, "chapter": 18, "thumb": "data/iran_war/thumbs/18.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "日本への影響", "start": 555.01, "end": 588.27, "scene": 19, "chapter": 18, "thumb": "data/iran_war/thumbs/19.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "まとめ", "start": 588.27, "end": 617.24, "scene": 20, "chapter": 18, "thumb": "data/iran_war/thumbs/20.jpg?v=a6a258b1a1158e47d4"}, {"kind": "scene", "num": null, "title": "参考にした資料", "start": 617.24, "end": 624.12, "scene": 21, "chapter": 18, "thumb": "data/iran_war/thumbs/21.jpg?v=a6a258b1a1158e47d4"}, {"kind": "ending", "num": null, "title": "エンディング", "start": 624.12, "end": 631.18, "scene": 22, "chapter": 18, "thumb": "data/iran_war/thumbs/22.jpg?v=a6a258b1a1158e47d4"}], "lines": [{"who": "zundamon", "text": "ずんだもんなのだ！今日は、ニュースで毎日聞く戦争の話なのだ。", "start": 0.8, "end": 5.21, "scene": 0}, {"who": "metan", "text": "四国めたんよ。アメリカ・イスラエルとイランの戦争ね。", "start": 5.46, "end": 9.03, "scene": 0}, {"who": "zundamon", "text": "でも正直、なんで戦っているのか、よくわからないのだ……", "start": 9.28, "end": 13.34, "scene": 0}, {"who": "metan", "text": "そう感じている人は、きっと多いと思うわ。", "start": 13.59, "end": 16.23, "scene": 0}, {"who": "metan", "text": "今回は、3つの疑問に順番に答えていくわ。", "start": 17.43, "end": 20.45, "scene": 1}, {"who": "zundamon", "text": "1つ目は、「なぜ始まったのか」なのだ。", "start": 20.7, "end": 23.62, "scene": 1}, {"who": "metan", "text": "2つ目は、「誰が悪いのか」。", "start": 23.87, "end": 25.74, "scene": 1}, {"who": "zundamon", "text": "3つ目は、「なぜ終わらないのか」なのだ！", "start": 25.99, "end": 28.89, "scene": 1}, {"who": "metan", "text": "どこかの国を応援したり責めたりはせず、事実を並べていくわね。", "start": 29.14, "end": 33.2, "scene": 1}, {"who": "metan", "text": "情報は、2026年10月7日時点のものよ。", "start": 33.45, "end": 36.97, "scene": 1}, {"who": "zundamon", "text": "まずは、登場する国を整理してほしいのだ。", "start": 38.17, "end": 41.26, "scene": 2}, {"who": "metan", "text": "地図で見てみましょう。", "start": 42.46, "end": 43.57, "scene": 3}, {"who": "metan", "text": "一方は、アメリカとイスラエル。イスラエルはここね。", "start": 43.82, "end": 47.19, "scene": 3}, {"who": "metan", "text": "アメリカは、中東の各地に基地を置いているわ。", "start": 47.44, "end": 50.29, "scene": 3}, {"who": "metan", "text": "もう一方がイラン。人口は約9千万人の大きな国よ。", "start": 50.54, "end": 54.51, "scene": 3}, {"who": "zundamon", "text": "イランは、1か国だけで戦っているのだ？", "start": 54.76, "end": 57.74, "scene": 3}, {"who": "metan", "text": "いいえ。イランが支援してきた武装組織も加わっているの。", "start": 57.99, "end": 61.67, "scene": 3}, {"who": "metan", "text": "レバノンのヒズボラ、イエメンのフーシ派、イラクの民兵組織ね。", "start": 61.92, "end": 65.82, "scene": 3}, {"who": "zundamon", "text": "あちこちに仲間がいるのだ！", "start": 66.07, "end": 67.81, "scene": 3}, {"who": "metan", "text": "サウジアラビアやUAEなど、湾岸の国々も巻き込まれたわ。", "start": 68.06, "end": 72.07, "scene": 3}, {"who": "metan", "text": "アメリカ軍の基地があるため、イランの攻撃を受けたの。", "start": 72.32, "end": 75.56, "scene": 3}, {"who": "metan", "text": "そして、間に入って話をまとめようとしているのが、パキスタンなどよ。", "start": 75.81, "end": 80.11, "scene": 3}, {"who": "zundamon", "text": "思ったより、たくさんの国が関わっているのだ。", "start": 80.36, "end": 83.48, "scene": 3}, {"who": "zundamon", "text": "そもそも、どうして仲が悪いのだ？", "start": 84.68, "end": 87.13, "scene": 4}, {"who": "metan", "text": "始まりは、1979年のイラン革命までさかのぼるわ。", "start": 88.33, "end": 92.5, "scene": 5}, {"who": "metan", "text": "親米の王様の政府が倒れて、イスラム教の指導者が治める国になったの。", "start": 92.75, "end": 97.53, "scene": 5}, {"who": "metan", "text": "新しい政府はアメリカと国交を断ち、イスラエルも国として認めなかったわ。", "start": 97.78, "end": 102.33, "scene": 5}, {"who": "zundamon", "text": "そこから、47年も対立しているのだ……", "start": 102.58, "end": 105.64, "scene": 5}, {"who": "metan", "text": "大きな争点になったのが、イランの核開発よ。", "start": 105.89, "end": 108.82, "scene": 5}, {"who": "metan", "text": "イランは「発電のため」と説明してきたわ。", "start": 109.07, "end": 111.93, "scene": 5}, {"who": "metan", "text": "でもアメリカやイスラエルは、核兵器を作る気だと疑ってきたの。", "start": 112.18, "end": 116.0, "scene": 5}, {"who": "metan", "text": "2015年には、核開発を制限する代わりに制裁を解く「核合意」ができたわ。", "start": 116.25, "end": 122.01, "scene": 5}, {"who": "metan", "text": "でも2018年、トランプ政権1期目のアメリカが、核合意から抜けたの。", "start": 122.26, "end": 127.16, "scene": 5}, {"who": "zundamon", "text": "せっかくの約束が、なくなっちゃったのだ？", "start": 127.41, "end": 130.23, "scene": 5}, {"who": "metan", "text": "ええ。制裁が戻り、イランも核開発を再び進めたわ。", "start": 130.48, "end": 134.88, "scene": 5}, {"who": "metan", "text": "そして、ここ数年で対立が一気に激しくなったの。", "start": 136.08, "end": 139.23, "scene": 6}, {"who": "metan", "text": "2023年にガザで戦争が始まり、イスラエルと親イラン勢力の衝突が広がったわ。", "start": 139.48, "end": 145.1, "scene": 6}, {"who": "metan", "text": "2025年6月には、イスラエルがイランの核施設などを攻撃したの。", "start": 145.35, "end": 149.82, "scene": 6}, {"who": "metan", "text": "アメリカも爆撃に加わって、12日間で停戦。これが「12日間戦争」よ。", "start": 150.07, "end": 156.15, "scene": 6}, {"who": "zundamon", "text": "去年も戦っていたのだ！？", "start": 156.4, "end": 158.2, "scene": 6}, {"who": "metan", "text": "2025年の暮れからは、イラン国内で大規模な反政府デモが起きたわ。", "start": 158.45, "end": 162.93, "scene": 6}, {"who": "metan", "text": "治安部隊の発砲で、少なくとも数千人が亡くなったと報じられているの。", "start": 163.18, "end": 167.75, "scene": 6}, {"who": "metan", "text": "2026年に入ると、アメリカは中東に大部隊を集めながら、核交渉も続けたわ。", "start": 168.0, "end": 173.8, "scene": 6}, {"who": "metan", "text": "2月26日の協議では、「来週また話し合う」ことになっていたの。", "start": 174.05, "end": 178.55, "scene": 6}, {"who": "zundamon", "text": "じゃあ、話し合いで解決しそうだったのだ？", "start": 178.8, "end": 181.88, "scene": 6}, {"who": "metan", "text": "……ところが、その2日後に戦争が始まったの。", "start": 182.13, "end": 184.86, "scene": 6}, {"who": "metan", "text": "2月28日、アメリカとイスラエルが、イラン全土を一斉に空爆したわ。", "start": 186.06, "end": 190.93, "scene": 7}, {"who": "metan", "text": "最初の攻撃で、最高指導者のハメネイ師や、政府の幹部が多数亡くなったの。", "start": 191.18, "end": 196.54, "scene": 7}, {"who": "zundamon", "text": "国のトップが、いきなり……！どうして攻撃したのだ？", "start": 196.79, "end": 200.35, "scene": 7}, {"who": "metan", "text": "アメリカが挙げた主な理由は、3つあるわ。", "start": 200.6, "end": 203.31, "scene": 7}, {"who": "metan", "text": "1つ目は、イランに核兵器を持たせないこと。", "start": 203.56, "end": 206.26, "scene": 7}, {"who": "metan", "text": "2つ目は、イランが中東の武装組織を支援してきたこと。", "start": 206.51, "end": 210.01, "scene": 7}, {"who": "metan", "text": "3つ目は、デモの弾圧などを挙げて、今の体制を変えることよ。", "start": 210.26, "end": 214.38, "scene": 7}, {"who": "metan", "text": "イスラエルは、自国への脅威を取り除く「先制攻撃」だと説明したわ。", "start": 214.63, "end": 219.81, "scene": 7}, {"who": "zundamon", "text": "イランは、本当に核兵器を作っていたのだ？", "start": 220.06, "end": 223.36, "scene": 7}, {"who": "metan", "text": "IAEAは、兵器を作っている証拠は見つけていないの。", "start": 223.61, "end": 227.3, "scene": 7}, {"who": "metan", "text": "ただ、イランが査察を制限していて、確かめきれない状態でもあったわ。", "start": 227.55, "end": 232.0, "scene": 7}, {"who": "zundamon", "text": "はっきりしないまま、始まってしまったのだ……", "start": 232.25, "end": 234.99, "scene": 7}, {"who": "metan", "text": "イランはすぐに反撃したわ。", "start": 236.19, "end": 237.79, "scene": 8}, {"who": "metan", "text": "イスラエルだけでなく、湾岸の国々にある米軍基地にもミサイルを撃ったの。", "start": 238.04, "end": 242.47, "scene": 8}, {"who": "metan", "text": "さらに、原油の通り道のホルムズ海峡を、事実上ふさいだわ。", "start": 242.72, "end": 247.03, "scene": 8}, {"who": "zundamon", "text": "ホルムズ海峡って、そんなに大事なのだ？", "start": 247.28, "end": 250.16, "scene": 8}, {"who": "metan", "text": "世界の石油と天然ガスの、約5分の1が通る海の道よ。", "start": 250.41, "end": 254.41, "scene": 8}, {"who": "metan", "text": "3月2日には、レバノンのヒズボラもイスラエルを攻撃したわ。", "start": 254.66, "end": 258.45, "scene": 8}, {"who": "metan", "text": "イスラエルはレバノン南部に地上部隊を送り、戦いはレバノンにも広がったの。", "start": 258.7, "end": 263.38, "scene": 8}, {"who": "metan", "text": "3月8日、ハメネイ師の次男モジタバ師が、新しい最高指導者になったわ。", "start": 263.63, "end": 268.49, "scene": 8}, {"who": "zundamon", "text": "ここまでが「なぜ始まったか」なのだ？", "start": 268.74, "end": 271.71, "scene": 8}, {"who": "metan", "text": "ええ。長い対立と核の問題があり、交渉の途中で攻撃が始まった。", "start": 271.96, "end": 277.08, "scene": 8}, {"who": "metan", "text": "それに反撃が重なって、周りの国まで広がった、という流れね。", "start": 277.33, "end": 281.53, "scene": 8}, {"who": "zundamon", "text": "こんなに広がって、止める人はいなかったのだ？", "start": 282.73, "end": 285.84, "scene": 9}, {"who": "metan", "text": "4月8日、パキスタンの仲介で、2週間の停戦が決まったわ。", "start": 287.04, "end": 291.45, "scene": 10}, {"who": "metan", "text": "でも、レバノンが停戦に含まれるかで、言い分が食い違ったの。", "start": 291.7, "end": 295.8, "scene": 10}, {"who": "metan", "text": "イスラエルはレバノンを大規模に攻撃し、イランは海峡を再び止めたわ。", "start": 296.05, "end": 300.43, "scene": 10}, {"who": "metan", "text": "4月11日からの話し合いは21時間続いたけど、合意できなかったの。", "start": 300.68, "end": 305.53, "scene": 10}, {"who": "metan", "text": "するとアメリカは、イランの港に出入りする船を止める、海上封鎖を始めたわ。", "start": 305.78, "end": 310.66, "scene": 10}, {"who": "zundamon", "text": "イランは海峡を止めて、アメリカはイランの港を止めたのだ？", "start": 310.91, "end": 314.84, "scene": 10}, {"who": "metan", "text": "そう。「二重封鎖」と呼ばれる状態ね。", "start": 315.09, "end": 318.03, "scene": 10}, {"who": "metan", "text": "6月17日、両国の大統領が「イスラマバード覚書」に署名したわ。", "start": 318.28, "end": 323.7, "scene": 10}, {"who": "metan", "text": "60日間の停戦延長と、海峡の再開、封鎖の解除が決まったの。", "start": 323.95, "end": 328.97, "scene": 10}, {"who": "zundamon", "text": "やったのだ！これで終わりなのだ！", "start": 329.22, "end": 331.29, "scene": 10}, {"who": "metan", "text": "……ただ、核の問題は「60日の間に話し合う」と先送りされていたの。", "start": 331.54, "end": 336.59, "scene": 10}, {"who": "metan", "text": "7月7日、イランがホルムズ海峡でタンカー3隻を攻撃したわ。", "start": 337.79, "end": 342.05, "scene": 11}, {"who": "metan", "text": "アメリカはすぐにイランを空爆し、覚書は事実上崩れてしまったの。", "start": 342.3, "end": 346.64, "scene": 11}, {"who": "metan", "text": "海上封鎖も再開され、8月17日には60日の期限も過ぎたわ。", "start": 346.89, "end": 351.7, "scene": 11}, {"who": "zundamon", "text": "せっかくの約束が、また……", "start": 351.95, "end": 353.91, "scene": 11}, {"who": "metan", "text": "9月には、イエメンのフーシ派が、紅海の入り口の海峡の周りを押さえたの。", "start": 354.16, "end": 359.0, "scene": 11}, {"who": "metan", "text": "サウジの船を狙うと宣言して、原油は1バレル100ドルを超えたわ。", "start": 359.25, "end": 363.27, "scene": 11}, {"who": "metan", "text": "そして10月、アメリカは3隻目の空母を中東に向かわせているわ。", "start": 363.52, "end": 367.63, "scene": 11}, {"who": "metan", "text": "イランは「7つの条件を満たすまで、海峡は開けない」と言っているの。", "start": 367.88, "end": 372.5, "scene": 11}, {"who": "zundamon", "text": "結局、今も戦争中ってことなのだ……", "start": 372.75, "end": 375.6, "scene": 11}, {"who": "metan", "text": "ええ。ただ、カタールを通じたやり取りは、今も続いているわ。", "start": 375.85, "end": 380.29, "scene": 11}, {"who": "zundamon", "text": "で、結局どっちが悪いのだ？", "start": 381.49, "end": 383.92, "scene": 12}, {"who": "metan", "text": "気になるわよね。でも、一言で決めるのは難しいの。", "start": 385.12, "end": 388.65, "scene": 13}, {"who": "metan", "text": "そこで、国連が両方の側をどう評価したかを並べてみるわ。", "start": 388.9, "end": 392.66, "scene": 13}, {"who": "metan", "text": "まず、開戦の日の国連事務総長の声明よ。", "start": 392.91, "end": 396.15, "scene": 13}, {"who": "metan", "text": "アメリカとイスラエルの攻撃は、国連憲章などに違反すると非難したわ。", "start": 396.4, "end": 400.74, "scene": 13}, {"who": "metan", "text": "同時に、イランの周りの国々への反撃も、主権を侵すと非難したの。", "start": 400.99, "end": 405.61, "scene": 13}, {"who": "zundamon", "text": "両方とも、非難されているのだ。", "start": 405.86, "end": 408.15, "scene": 13}, {"who": "metan", "text": "9月には、国連が設けた調査団が報告書を出したわ。", "start": 408.4, "end": 411.94, "scene": 13}, {"who": "metan", "text": "アメリカ軍による学校などへの攻撃に、戦争犯罪の疑いがあるとしたの。", "start": 412.19, "end": 416.99, "scene": 13}, {"who": "metan", "text": "イランのデモ弾圧には、人道に対する罪の疑いがあるとしたわ。", "start": 417.24, "end": 421.19, "scene": 13}, {"who": "metan", "text": "一方で、当事者はどちらも「自分たちは自衛している」と説明しているの。", "start": 421.44, "end": 426.46, "scene": 13}, {"who": "metan", "text": "アメリカ政府は、調査団の報告を否定しているわ。", "start": 426.71, "end": 429.97, "scene": 13}, {"who": "zundamon", "text": "どっちの側にも、問題だと言われていることがあるのだ……", "start": 430.22, "end": 433.76, "scene": 13}, {"who": "metan", "text": "そう。どの立場から見るかで、印象はかなり変わるの。", "start": 434.01, "end": 437.53, "scene": 13}, {"who": "metan", "text": "だからニュースを見るときは、「誰の発表か」を気にするといいわ。", "start": 437.78, "end": 441.61, "scene": 13}, {"who": "zundamon", "text": "発表した人の立場も、一緒に見るのだ！", "start": 441.86, "end": 444.8, "scene": 13}, {"who": "zundamon", "text": "最後の疑問なのだ。どうして終わらないのだ？", "start": 446.0, "end": 449.0, "scene": 14}, {"who": "metan", "text": "理由は、大きく4つあるわ。1つ目は、求めるものの順番が違うこと。", "start": 450.2, "end": 455.03, "scene": 15}, {"who": "metan", "text": "アメリカがまず求めているのは、核の問題の解決よ。", "start": 455.28, "end": 458.63, "scene": 15}, {"who": "metan", "text": "ウランの濃縮をやめさせて、核兵器への道を断ちたいの。", "start": 458.88, "end": 462.41, "scene": 15}, {"who": "metan", "text": "イランが先に求めているのは、封鎖の解除と、凍結された資産の返還。", "start": 462.66, "end": 467.33, "scene": 15}, {"who": "metan", "text": "それに、レバノンも含めた、すべての戦線での停戦よ。", "start": 467.58, "end": 471.4, "scene": 15}, {"who": "zundamon", "text": "お互いに「そっちが先」って言っているのだ？", "start": 471.65, "end": 475.11, "scene": 15}, {"who": "metan", "text": "そういうこと。順番が決まらないと、話が前に進まないの。", "start": 475.36, "end": 479.41, "scene": 15}, {"who": "metan", "text": "2つ目は、両方が「封鎖」という切り札を持っていることよ。", "start": 480.61, "end": 484.75, "scene": 16}, {"who": "metan", "text": "イランは、ホルムズ海峡を通る船を止めているわ。", "start": 485.0, "end": 487.98, "scene": 16}, {"who": "metan", "text": "アメリカは、イランの港に出入りする船を止めているの。", "start": 488.23, "end": 491.32, "scene": 16}, {"who": "metan", "text": "そのため、イランの石油の輸出は、ほぼゼロになったと伝えられているわ。", "start": 491.57, "end": 495.83, "scene": 16}, {"who": "zundamon", "text": "それなら、イランはすぐに困るのだ？", "start": 496.08, "end": 498.61, "scene": 16}, {"who": "metan", "text": "苦しいはずよ。でも海峡が止まると、世界中で石油の値段が上がるの。", "start": 498.86, "end": 503.63, "scene": 16}, {"who": "metan", "text": "どちらも「相手が先に困って譲る」と考えて、我慢比べになっているわ。", "start": 503.88, "end": 508.79, "scene": 16}, {"who": "zundamon", "text": "我慢比べの間も、みんなが困るのだ……", "start": 509.04, "end": 511.85, "scene": 16}, {"who": "metan", "text": "3つ目は、お互いに相手の約束を信用していないことよ。", "start": 513.05, "end": 516.69, "scene": 17}, {"who": "metan", "text": "イランから見ると、アメリカは核合意から抜け、交渉中に攻撃してきた相手。", "start": 516.94, "end": 521.77, "scene": 17}, {"who": "metan", "text": "アメリカから見ると、イランは停戦中にタンカーを攻撃した相手なの。", "start": 522.02, "end": 526.22, "scene": 17}, {"who": "zundamon", "text": "どっちも「信じられない」と思っているのだ……", "start": 526.47, "end": 529.53, "scene": 17}, {"who": "metan", "text": "4つ目は、決める人がまとまっていないことね。", "start": 529.78, "end": 532.52, "scene": 17}, {"who": "metan", "text": "イスラエルは覚書の当事者ではなく、レバノンへの攻撃を続けているわ。", "start": 532.77, "end": 537.26, "scene": 17}, {"who": "metan", "text": "イランの側も、軍の強硬派が強い力を持っていると言われているの。", "start": 537.51, "end": 541.54, "scene": 17}, {"who": "metan", "text": "7月のタンカー攻撃も、強硬派の幹部の判断だったと報じられているわ。", "start": 541.79, "end": 546.4, "scene": 17}, {"who": "zundamon", "text": "合意しても、守られるかわからないってことなのだ。", "start": 546.65, "end": 549.83, "scene": 17}, {"who": "zundamon", "text": "ところで、日本にも関係がある話なのだ？", "start": 551.03, "end": 554.31, "scene": 18}, {"who": "metan", "text": "大ありよ。日本は、原油の9割以上を中東から輸入しているの。", "start": 555.51, "end": 560.09, "scene": 19}, {"who": "metan", "text": "その多くが、ホルムズ海峡を通って運ばれてくるわ。", "start": 560.34, "end": 563.52, "scene": 19}, {"who": "metan", "text": "3月16日、ガソリンの全国平均は1リットル190.8円と、過去最高になったの。", "start": 563.77, "end": 570.22, "scene": 19}, {"who": "metan", "text": "今は政府の補助金で、170円前後に抑えているわ。", "start": 570.47, "end": 574.49, "scene": 19}, {"who": "metan", "text": "10月8日からの補助は、1リットルあたり42.4円よ。", "start": 574.74, "end": 578.63, "scene": 19}, {"who": "zundamon", "text": "補助がなかったら、もっと高いってことなのだ！", "start": 578.88, "end": 581.67, "scene": 19}, {"who": "metan", "text": "ええ。天然ガスの輸送も滞っていて、電気代や物の値段にも影響しているわ。", "start": 581.92, "end": 587.57, "scene": 19}, {"who": "zundamon", "text": "最後に、まとめるのだ！", "start": 588.77, "end": 590.58, "scene": 20}, {"who": "metan", "text": "なぜ始まったのか。長い対立と核の問題があり、交渉の途中で攻撃が始まったわ。", "start": 590.83, "end": 596.5, "scene": 20}, {"who": "zundamon", "text": "誰が悪いのか。国連は、両方の側の行動を問題だと言っているのだ。", "start": 596.75, "end": 601.89, "scene": 20}, {"who": "metan", "text": "なぜ終わらないのか。要求の順番、封鎖の我慢比べ、不信、まとめ役の不在ね。", "start": 602.14, "end": 608.12, "scene": 20}, {"who": "zundamon", "text": "これからどうなるかは、アメリカとイランの次の一手しだいなのだ。", "start": 608.37, "end": 612.31, "scene": 20}, {"who": "metan", "text": "状況は毎日変わるから、最新のニュースもあわせて確かめてね。", "start": 612.56, "end": 616.54, "scene": 20}, {"who": "metan", "text": "参考にした資料は、こちらよ。", "start": 617.74, "end": 619.78, "scene": 21}, {"who": "zundamon", "text": "気になった人は、自分でも確かめてみてほしいのだ。", "start": 620.03, "end": 623.42, "scene": 21}, {"who": "zundamon", "text": "今日はここまでなのだ！ご視聴ありがとうなのだ！", "start": 624.62, "end": 627.65, "scene": 22}, {"who": "metan", "text": "高評価とチャンネル登録も、よろしくね。", "start": 627.9, "end": 630.48, "scene": 22}], "cast": {"metan": {"name": "四国めたん", "color": "#d43a86", "position": "left", "voice": "VOICEVOX:四国めたん", "stats": {"lines": 110, "seconds": 451.11, "chars": 3131, "ending": ["たわ", 25]}, "portrait": {"idle": "data/cast/metan/idle.webp?v=3-1a114ac0292", "blink": "data/cast/metan/blink.webp?v=3-1a114ac0292", "talk": "data/cast/metan/talk.webp?v=3-1a114ac0292", "joy": "data/cast/metan/joy.webp?v=3-1a114ac0292"}}, "zundamon": {"name": "ずんだもん", "color": "#2f9a3a", "position": "right", "voice": "VOICEVOX:ずんだもん", "stats": {"lines": 40, "seconds": 120.42, "chars": 814, "ending": ["のだ", 43]}, "portrait": {"idle": "data/cast/zundamon/idle.webp?v=3-1a114abfbbf", "blink": "data/cast/zundamon/blink.webp?v=3-1a114abfbbf", "talk": "data/cast/zundamon/talk.webp?v=3-1a114abfbbf", "joy": "data/cast/zundamon/joy.webp?v=3-1a114abfbbf"}}}, "summary": [{"text": "**なぜ始まった？**", "sub": "47年の対立と核の問題。交渉の途中で攻撃が始まった"}, {"text": "**誰が悪い？**", "sub": "国連は、両方の側の行動を問題視している"}, {"text": "**なぜ終わらない？**", "sub": "要求の順番・封鎖の我慢比べ・不信・まとめ役の不在"}, {"text": "**これから**", "sub": "大規模な攻撃の再開か、カタール経由の交渉か"}], "sources": [{"text": "国連事務総長の声明（2026年2月28日）／国連安全保障理事会 決議2817号（3月11日）", "note": ""}, {"text": "国連「イランに関する独立国際事実調査団」報告（9月17日）", "note": "AP・ロイター等の報道による"}, {"text": "米国・イラン「イスラマバード覚書」（6月17日署名）", "note": ""}, {"text": "Al Jazeera（2月28日、6月17日、10月4日）、New York Times（7月25日）、Bloomberg、CNN ほか各社報道", "note": ""}, {"text": "The National（10月4日）、Iran International（10月3〜4日）", "note": "10月の最新動向"}, {"text": "石油情報センター・資源エネルギー庁「燃料油価格定額引き下げ措置」", "note": "ガソリン価格と補助単価"}, {"text": "Wikipedia 英語版「2026 Iran war」「Islamabad Memorandum」「2025–2026 Iranian protests」ほか", "note": "経緯の把握に使用し、数値は報道で確認"}, {"text": "地図：Natural Earth（パブリックドメイン）をもとに作成", "note": ""}], "credits": [["音声", "VOICEVOX:ずんだもん / VOICEVOX:四国めたん"], ["立ち絵", "坂本アヒル"], ["音楽", "音楽：魔王魂"], ["効果音", "効果音ラボ"], ["地図", "Natural Earth"], ["フォント", "M PLUS Rounded 1c / Dela Gothic One"], ["情報", "2026年10月7日時点"]], "no": 4}], "cast": {"metan": {"name": "四国めたん", "color": "#d43a86", "voice": "VOICEVOX:四国めたん", "lines": 223, "seconds": 880.64, "chars": 6162, "videos": 4, "portrait": {"idle": "data/cast/metan/idle.webp?v=3-1a114ac0292", "blink": "data/cast/metan/blink.webp?v=3-1a114ac0292", "talk": "data/cast/metan/talk.webp?v=3-1a114ac0292", "joy": "data/cast/metan/joy.webp?v=3-1a114ac0292"}, "ending": ["るわ", 32]}, "zundamon": {"name": "ずんだもん", "color": "#2f9a3a", "voice": "VOICEVOX:ずんだもん", "lines": 97, "seconds": 316.42, "chars": 2120, "videos": 4, "portrait": {"idle": "data/cast/zundamon/idle.webp?v=3-1a114abfbbf", "blink": "data/cast/zundamon/blink.webp?v=3-1a114abfbbf", "talk": "data/cast/zundamon/talk.webp?v=3-1a114abfbbf", "joy": "data/cast/zundamon/joy.webp?v=3-1a114abfbbf"}, "ending": ["のだ", 114]}}, "site": {"url": "https://dikmri.github.io/zunda-archive/", "repo": "dikmri/zunda-archive"}};
